#!/usr/bin/env bash
# ============================================================
# AgOpenGPS → Python Migration Issues Creator
# Usage: GH_TOKEN=your_pat bash create_migration_issues.sh
# Target repo: Gurpreetssandhu/AgOpenGps_migr_py
# Requires: curl, a GitHub PAT with 'repo' scope in GH_TOKEN
# ============================================================
set -euo pipefail
REPO="Gurpreetssandhu/AgOpenGps_migr_py"
TOKEN="${GH_TOKEN:-${GITHUB_TOKEN:-}}"

if [[ -z "$TOKEN" ]]; then
  echo "Error: GH_TOKEN or GITHUB_TOKEN must be set to a GitHub PAT with 'repo' scope." >&2
  echo "Example: GH_TOKEN=ghp_xxxx bash create_migration_issues.sh" >&2
  exit 1
fi

gh_api() {
  curl -s -X POST \
    -H "Authorization: token $TOKEN" \
    -H "Content-Type: application/json" \
    -H "Accept: application/vnd.github.v3+json" \
    "https://api.github.com/repos/$REPO/issues" \
    -d "$1"
}

create_label() {
  local name="$1" color="$2" description="$3"
  local http_code
  http_code=$(curl -s -o /dev/null -w "%{http_code}" -X POST \
    -H "Authorization: token $TOKEN" \
    -H "Content-Type: application/json" \
    "https://api.github.com/repos/$REPO/labels" \
    -d "{\"name\":\"$name\",\"color\":\"$color\",\"description\":\"$description\"}")
  # 201 = created, 422 = already exists — both are acceptable
  if [[ "$http_code" != "201" && "$http_code" != "422" ]]; then
    echo "Warning: unexpected HTTP $http_code when creating label '$name'" >&2
  fi
}

